```js
function applyFilters({ topic, level }) {
  renderLessons(topic, level);
}

function setFilters(filters) {
  const url = new URL(location.href);
  url.searchParams.set("topic", filters.topic);
  url.searchParams.set("level", filters.level);
  history.pushState(filters, "", url);   // new history entry, no reload.
  applyFilters(filters);
}

window.addEventListener("popstate", () => {
  const p = new URL(location.href).searchParams;
  applyFilters({ topic: p.get("topic") ?? "all", level: p.get("level") ?? "any" });
});
```

